window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"RvYuTODMOZY","speaker":"Vijitha Herath","role":"Foreign Minister","country":"Sri Lanka","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=RvYuTODMOZY","date":"20260928","title":"🇱🇰 Sri Lanka - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1249,"words":2253,"counts":{"claims":33,"promises":2,"attacks":0},"topics":[{"topic":"Sri Lanka governance","share":0.1171,"seconds":146},{"topic":"Sri Lanka economy","share":0.1045,"seconds":130},{"topic":"UN reform","share":0.0691,"seconds":86},{"topic":"UN multilateralism","share":0.064,"seconds":80},{"topic":"Sri Lanka technology","share":0.0621,"seconds":78},{"topic":"Sri Lanka humanitarian aid","share":0.0572,"seconds":71},{"topic":"Climate change","share":0.0567,"seconds":71},{"topic":"Gaza conflict","share":0.0556,"seconds":69},{"topic":"West Asia conflicts","share":0.0551,"seconds":69},{"topic":"Sri Lanka peacekeeping","share":0.0546,"seconds":68},{"topic":"Nuclear weapons","share":0.0534,"seconds":67},{"topic":"UN legitimacy","share":0.0524,"seconds":65},{"topic":"Sri Lanka civil war","share":0.0499,"seconds":62},{"topic":"Palestine-Israel","share":0.0498,"seconds":62},{"topic":"UNGA session","share":0.0493,"seconds":62},{"topic":"Ocean conservation","share":0.0492,"seconds":61}],"timeline":[[3,65,"UNGA session"],[67,133,"UN legitimacy"],[136,216,"Sri Lanka governance"],[219,287,"Sri Lanka economy"],[289,360,"Climate change"],[363,425,"Sri Lanka civil war"],[426,495,"West Asia conflicts"],[496,568,"Sri Lanka humanitarian aid"],[570,640,"Gaza conflict"],[641,703,"Palestine-Israel"],[706,774,"Sri Lanka peacekeeping"],[777,843,"Nuclear weapons"],[845,908,"Sri Lanka economy"],[909,971,"Ocean conservation"],[972,1039,"Sri Lanka governance"],[1041,1119,"Sri Lanka technology"],[1121,1201,"UN multilateralism"],[1204,1264,"UN reform"],[1267,1292,"UN reform"]],"stances":{"UNGA session":"Vijitha Herath congratulates the newly elected President of the General Assembly and expresses Sri Lanka's support for his mandate while acknowledging the predecessor's work.","UN legitimacy":"Vijitha Herath states that the theme of restoring trust addresses global challenges including unresolved conflicts, humanitarian crises, climate disasters, widening inequalities, and rapid technological advances outpacing governance.","Sri Lanka governance":"Vijitha Herath states that Sri Lanka is undergoing a historic transformation to rebuild trust through action and delivery following a mandate for change.","Sri Lanka economy":"Vijitha Herath states that Sri Lanka has restored macroeconomic stability and been reclassified as an upper-middle-income economy despite recent crises, while acknowledging ongoing vulnerabilities.","Climate change":"Vijitha Herath states that climate change imposes severe human and economic costs, particularly on nations with low emissions, and asserts that Sri Lanka is committed to renewable energy targets.","Sri Lanka civil war":"Vijitha Herath states that Sri Lanka suffered a protracted conflict for three decades, the guns fell silent 17 years ago, and the government is determined to prevent recurrence while strengthening institutions to heal deep wounds.","West Asia conflicts":"Vijitha Herath states that Sri Lanka is experiencing severe security, economic, and social impacts from conflicts in West Asia but continues to uphold international law and human life.","Sri Lanka humanitarian aid":"Vijitha Herath states that Sri Lanka prioritized human lives and acted based on international law and humanity while maintaining neutrality.","Gaza conflict":"Vijitha Herath expresses deep concern regarding the conflicts in West Asia and Gaza, emphasizing the need for adherence to international law and highlighting the disparity between military spending and human suffering.","Palestine-Israel":"Vijitha Herath reaffirms support for dialogue, Palestinian statehood within pre-1967 borders, and the implementation of a ceasefire in Gaza.","Sri Lanka peacekeeping":"Vijitha Herath states that Sri Lanka has contributed over 21,000 personnel to UN missions since 1957 and continues to serve with distinction in challenging environments.","Nuclear weapons":"Vijitha Herath states that the only real guarantee against nuclear weapons is their total and verifiable elimination.","Ocean conservation":"Vijitha Herath states that Sri Lanka remains committed to preserving the oceans as a shared space for peaceful use and reaffirms its commitment to safeguarding them as a common heritage of humankind.","Sri Lanka technology":"Vijitha Herath states that Sri Lanka is developing a digital future with national AI ethical guidelines and calls for responsible technology use consistent with international law.","UN multilateralism":"Vijitha Herath describes the UN as an indispensable partner for Sri Lanka and emphasizes the need to reform it to be more effective, representative, and responsive.","UN reform":"Vijitha Herath supports the UN 80 initiative as a means to strengthen the United Nations and advance meaningful, inclusive reform that narrows global divides."},"claims":[{"t":35,"quote":"congratulate you, Dr. Khalilur Rahman, on your election as President of the 81st Session of the General Assembly.","topic":"UNGA session","kind":"fact"},{"t":55,"quote":"We also convey our deep appreciation to your predecessor, Madam Annalena Baerbock, for her able stewardship of the 18th Session.","topic":"UNGA session","kind":"fact"},{"t":113,"quote":"The erosion of trust is reflected in unresolved conflicts, humanitarian crisis that outpaces available resources, increasingly frequent climate disasters, widening inequalities, and technological advances that are moving faster than governance.","topic":"UN legitimacy","kind":"fact"},{"t":166,"quote":"2 years ago, marking a watershed moment in our the people of Sri Lanka, representing all communities and walks of life, gave a resounding mandate to the government of President Anura Kumara Dissanayake to address these challenges and institute meaningful change.","topic":"Sri Lanka governance","kind":"fact"},{"t":188,"quote":"Since then, our government has been working with determination to rebuild trust from the ground up.","topic":"Sri Lanka governance","kind":"fact"},{"t":231,"quote":"my country has restored macroeconomic stability following the economic crisis of 2022.","topic":"Sri Lanka economy","kind":"fact"},{"t":241,"quote":"Sri Lanka has been reclassified by the World Bank as an upper-middle-income economy","topic":"Sri Lanka economy","kind":"fact"},{"t":279,"quote":"Cyclone Ditwa was one of the worst natural disasters in Sri Lanka's recent history","topic":"Sri Lanka economy","kind":"fact"},{"t":289,"quote":"The calamity resulted in the loss of hundreds of lives and affected more than 2 million people.","topic":"Climate change","kind":"number"},{"t":351,"quote":"For our part, Sri Lanka is on track towards achieving 70% renewable energy by 2030 and carbon neutrality by 2050.","topic":"Climate change","kind":"number"},{"t":365,"quote":"for three decades, Sri Lanka suffered a protracted conflict that caused enormous loss and suffering to all our","topic":"Sri Lanka civil war","kind":"fact"},{"t":376,"quote":"the guns fell silent 17 years ago, the deep wounds of that conflict remain, and much remains to be done to heal","topic":"Sri Lanka civil war","kind":"fact"},{"t":437,"quote":"Sri Lanka, like many other countries, is experiencing the severe impact of conflicts in West Asia and elsewhere.","topic":"West Asia conflicts","kind":"fact"},{"t":447,"quote":"As an island nation situated at the crossroads of the Indian Ocean and as a country with a large number of migrant workers in West Asia, these developments have direct security, economic, and social implications for I am pleased to note that even during these challenging times, Sri Lanka has continued to uphold its commitments to international law and ensure sanctity of human life and human Mr. President, in March this year, a highly volatile geopolitical landscape, Sri Lanka found a ship of a party to a conflict in distress close to our territorial waters with many sailors' lives in peril.","topic":"West Asia conflicts","kind":"fact"},{"t":496,"quote":"We took the difficult path of navigating a wilderness of sensitivities and marshaling our limited nation's resources to rescue and look after the wounded and sick.","topic":"Sri Lanka humanitarian aid","kind":"fact"},{"t":510,"quote":"Hard as it was, we went on to rescue hundreds more.","topic":"Sri Lanka humanitarian aid","kind":"number"},{"t":600,"quote":"the global security environment has deteriorated significantly in recent","topic":"Gaza conflict","kind":"fact"},{"t":613,"quote":"vast resources continue to be spent on weapons while children face starvation and are deprived of medicine","topic":"Gaza conflict","kind":"fact"},{"t":659,"quote":"We are among the countries that first recognized Palestine as a distinct state in in the 1980s.","topic":"Palestine-Israel","kind":"fact"},{"t":716,"quote":"having deployed more than 21,000 personnel on numerous missions since 1957","topic":"Sri Lanka peacekeeping","kind":"number"},{"t":725,"quote":"Our blue helmets, through their dedication and service over many years, have earned the trust of local communities and the commendation of UN field missions","topic":"Sri Lanka peacekeeping","kind":"fact"},{"t":777,"quote":"At a time of rising geopolitical tensions and rhetoric of nuclear we remain firmly convinced that the only real guarantee against these weapons is their total and verifiable elimination.","topic":"Nuclear weapons","kind":"fact"},{"t":816,"quote":"We welcomed the civil commitment last including its call for urgent action to close the $4 financing gap for sustainable development in developing countries.","topic":"Nuclear weapons","kind":"number"},{"t":845,"quote":"Our national budget last year made historic allocations to the health care and education sectors.","topic":"Sri Lanka economy","kind":"fact"},{"t":852,"quote":"We take pride in our long-standing policy of free and universal health care and education","topic":"Sri Lanka economy","kind":"fact"},{"t":920,"quote":"Our nation's prosperity is closely linked to the Indian Ocean.","topic":"Ocean conservation","kind":"fact"},{"t":926,"quote":"As founding member of the agreement on marine biological diversity of areas beyond national jurisdiction, the BBNJ we reaffirm our commitment to safeguarding the oceans as a common heritage of humankind for present and future generations.","topic":"Ocean conservation","kind":"self_credit"},{"t":972,"quote":"In delivering on this mandate, we have placed good governance, anti-corruption, and institutional transparency at the core of a comprehensive national integrity drive that is being vigorously pursued.","topic":"Sri Lanka governance","kind":"fact"},{"t":1012,"quote":"Substantial progress has been made in strengthening the independence of institutions responsible for investigating and prosecuting bribery and corruption.","topic":"Sri Lanka governance","kind":"fact"},{"t":1041,"quote":"1 year on, our united as a nation national program has made significant including through the arrest of key figures in the narcotics supply chain.","topic":"Sri Lanka technology","kind":"fact"},{"t":1087,"quote":"We have developed national AI ethical guidelines in line with international frameworks.","topic":"Sri Lanka technology","kind":"fact"},{"t":1170,"quote":"For more than eight decades amidst its flaws and with much room for improvement the United Nations has given practical meaning to that promise.","topic":"UN multilateralism","kind":"fact"},{"t":1205,"quote":"Sri Lanka supports the UN 80 initiative as an opportunity to renew and strengthen the United Nations and advance advance meaningful reform.","topic":"UN reform","kind":"fact"}],"promises":[{"t":417,"quote":"We will continue to work tirelessly to build a nation that is more secure, inclusive, and united.","topic":"Sri Lanka civil war","kind":"promise"},{"t":537,"quote":"we will never hesitate to protect If there are actions that must be taken to protect human lives, we will not hesitate to take them under any circumstance.","topic":"Sri Lanka humanitarian aid","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"UNGA session","text":"I now give the floor to His Excellency Vijitha Herath, Minister for Foreign Affairs of Sri Lanka. &gt;&gt; Mr. President, Mr. Secretary General, Excellencies, ladies and gentlemen, allow me at the outset to congratulate you, Dr. Khalilur Rahman, on your election as President of the 81st Session of the General Assembly. On behalf of the Government of Sri I wish you every success and assure you of our fullest support in the discharge of your mandate. We also convey our deep appreciation to your predecessor, Madam Annalena Baerbock, for her able stewardship of the 18th Session."},{"t":67,"topic":"UN legitimacy","text":"Let me also take this opportunity to acknowledge the leadership of Secretary General Antonio Guterres as he concludes his term. Mr. President, seminal changes are taking place across the world at a pace faster than many institutions are able to adapt or People across the globe are demanding greater clarity, honesty, and action from their leaders and institutions. The theme of this year's General Debate, Restoring Trust, Managing a United Nations that delivers for all, goes to the heart of this challenge. The erosion of trust is reflected in unresolved conflicts, humanitarian crisis that outpaces available resources, increasingly frequent climate disasters, widening inequalities, and technological advances that are moving faster than governance."},{"t":136,"topic":"Sri Lanka governance","text":"these developments have contributed to a growing perception that global institutions are distant from the people they are meant to resolve. Sri Lanka understands this reality My country has on many occasions in the experienced the consequences of deficits in trust and breaches of the social 2 years ago, marking a watershed moment in our the people of Sri Lanka, representing all communities and walks of life, gave a resounding mandate to the government of President Anura Kumara Dissanayake to address these challenges and institute meaningful change. Since then, our government has been working with determination to rebuild trust from the ground up. We are building trust through action, not rhetoric, through delivery, discipline and the courage to confront Sri Lanka is therefore undergoing a historic transformation and rejuvenation."},{"t":219,"topic":"Sri Lanka economy","text":"Despite conflicts in several parts of the world, including in West Asia, and climate calamities, including the cyclone that struck Sri Lanka, my country has restored macroeconomic stability following the economic crisis of 2022. Sri Lanka has been reclassified by the World Bank as an upper-middle-income economy, and ratings agencies have recognized this positive trajectory. these developments do not fully reflect the vulnerabilities of countries exposed to debt and external shocks. While we work with our global partners to consolidate this hard-won stability, we remain conscious of the critical need to address the hardships faced by vulnerable communities. Cyclone Ditwa was one of the worst natural disasters in Sri Lanka's recent history and devastated several parts of our country."},{"t":289,"topic":"Climate change","text":"The calamity resulted in the loss of hundreds of lives and affected more than 2 million people. Livelihoods were disrupted and critical was destroyed. Having experienced this tragedy, we understand deeply the challenge posed by the Himalayan floods to the people of Nepal and China. We extend our deepest sympathies to the These tragic events demonstrate the enormous human and economic cost of climate change. its harshest consequences continue to be borne by countries that have contributed least to global emissions. The call for action on climate impact is not merely immediate. It is overdue. Climate justice must become an urgent For our part, Sri Lanka is on track towards achieving 70% renewable energy by 2030 and carbon neutrality by 2050."},{"t":363,"topic":"Sri Lanka civil war","text":"Mr. President, for three decades, Sri Lanka suffered a protracted conflict that caused enormous loss and suffering to all our the guns fell silent 17 years ago, the deep wounds of that conflict remain, and much remains to be done to heal We are determined to prevent a recurrence of such a tragedy and to pursue a path towards national unity and In this regard, our government is strengthening national institutions to address outstanding Throughout these two years, we have remained firm in our rejection of racism and religious extremism in all its forms and manifestations. We will continue to work tirelessly to build a nation that is more secure, inclusive, and united."},{"t":426,"topic":"West Asia conflicts","text":"A nation made stronger by the full richness of its Mr. President, in addition to the consequences of natural calamity, Sri Lanka, like many other countries, is experiencing the severe impact of conflicts in West Asia and elsewhere. As an island nation situated at the crossroads of the Indian Ocean and as a country with a large number of migrant workers in West Asia, these developments have direct security, economic, and social implications for I am pleased to note that even during these challenging times, Sri Lanka has continued to uphold its commitments to international law and ensure sanctity of human life and human Mr. President, in March this year, a highly volatile geopolitical landscape, Sri Lanka found a ship of a party to a conflict in distress close to our territorial waters with many sailors' lives in peril."},{"t":496,"topic":"Sri Lanka humanitarian aid","text":"We took the difficult path of navigating a wilderness of sensitivities and marshaling our limited nation's resources to rescue and look after the wounded and sick. Hard as it was, we went on to rescue hundreds more. We saw human lives in danger and we acted founding ourselves on international law and on humanity. While safeguarding our neutrality, we placed humanity above all else. As President Dissanayake has reiterated, we will never hesitate to protect If there are actions that must be taken to protect human lives, we will not hesitate to take them under any circumstance. This, Mr. President, is the Sri Lanka we wish to bring before the world, a small island nation with a big heart which believes that even in times of conflict and profound division, there remains a space for humanity."},{"t":570,"topic":"Gaza conflict","text":"And that is also what we wish to see reflected in the world. We need a world where our capacity to uphold humanity grows faster than our capacity to destroy it. That is the transformation we should It is for these reasons that we are paying by the developments in Gaza and the occupied Palestinian territories. Mr. President, the global security environment has deteriorated significantly in recent It is difficult to accept that in a world with so much wealth and vast resources continue to be spent on weapons while children face starvation and are deprived of medicine and Sri Lanka remains deeply concerned by the conflicts in West Asia and by the heavy cost being born far beyond the International law, including international humanitarian law, must be adhered to and respected by all parties."},{"t":641,"topic":"Palestine-Israel","text":"We reaffirm our position that dialogue is the only viable way forward. Sri Lanka continues to support the inalienable rights of the Palestinian including their right to We are among the countries that first recognized Palestine as a distinct state in in the 1980s. We stand in solidarity with the international community in calling for an independent and sovereign state of existing side by side with Israel in within the pre-1968 67 borders. We welcome the resolution of the Security Council on a ceasefire in Gaza and urge all parties to uphold it. Humanitarian assistance must reach civilians without obstruction. The recovery and reconstruction of Gaza must be an urgent priority."},{"t":706,"topic":"Sri Lanka peacekeeping","text":"Mr. President, Sri Lanka is proud of its long-standing contribution to United Nations in pursuit of global peace and security, having deployed more than 21,000 personnel on numerous missions since 1957. Our blue helmets, through their dedication and service over many years, have earned the trust of local communities and the commendation of UN field missions. they continue to serve with distinction in some of the most challenging environments under the UN flag, protecting vulnerable civilians, deterring violence, and helping war-torn communities transition from conflict to Sri Lanka has also long championed multilateral disarmament from our early call for an Indian Ocean Indian Ocean Zone of Peace to our leadership at the 1995 NPT review and extension conference."},{"t":777,"topic":"Nuclear weapons","text":"At a time of rising geopolitical tensions and rhetoric of nuclear we remain firmly convinced that the only real guarantee against these weapons is their total and verifiable elimination. Mr. President, as we approach 2030, we must deliver on the Sustainable Development Goals, which remain our collective blueprint for sustainable development. Sri Lanka once again calls for reform of the international financial system and for fairer rules governing debt and development finance. We welcomed the civil commitment last including its call for urgent action to close the $4 financing gap for sustainable development in developing countries. It is now time to translate those commitments into concrete action. We remain steadfast in recognizing poverty and inequality as factors requiring our urgent attention."},{"t":845,"topic":"Sri Lanka economy","text":"Our national budget last year made historic allocations to the health care and education sectors. We take pride in our long-standing policy of free and universal health care and education and remain committed to strengthening these important pillars of social While actively implementing all SDGs without discrimination we fully subscribe to and proactively engage with SDG 16 which underscores the importance of just and inclusive institutions that build and restore public trust and treat all people equally. Mr. President Sri Lanka has long championed and contributed towards a fair and peaceful order at sea under the United Nations Convention on the law of the sea, a legal regime which we have helped shape. We also support the work of the commission on the limits of the continental shelf."},{"t":909,"topic":"Ocean conservation","text":"We remain committed to preserving the oceans as a shared space for peaceful and sustainable use and for Our nation's prosperity is closely linked to the Indian Ocean. As founding member of the agreement on marine biological diversity of areas beyond national jurisdiction, the BBNJ we reaffirm our commitment to safeguarding the oceans as a common heritage of humankind for present and future generations. We look forward to the further operationalization of the agreement complementing the processes of the International Seabed Authority. Mr. President, one of the key pillars of the decisive mandate given to us by the people of Sri Lanka was to build a transparent and ethical nation."},{"t":972,"topic":"Sri Lanka governance","text":"In delivering on this mandate, we have placed good governance, anti-corruption, and institutional transparency at the core of a comprehensive national integrity drive that is being vigorously pursued. We have seen all too clearly how corruption weakens democracy and destroys trust. We continue to enforce the law against corruption without fear or favor, irrespective of a person's background or social standing. Investigations and prosecutions continue to progress without political Substantial progress has been made in strengthening the independence of institutions responsible for investigating and prosecuting bribery and corruption. My president, who addressed this assembly last year, also highlighted how narcotics and related organized crime have become a menace for many countries, as well as our government's comprehensive efforts to address this menace."},{"t":1041,"topic":"Sri Lanka technology","text":"1 year on, our united as a nation national program has made significant including through the arrest of key figures in the narcotics supply chain. Mr. President, we reiterate our call on the global community to promote meaningful technology transfers, ensure equitable access for developing nations, bridge the digital divide, and build safe, secure, and trust-trustworthy systems that leave no one behind. Sri Lanka is in the process of building digital future that includes everyone. We have developed national AI ethical guidelines in line with international frameworks. We must ensure that emerging technologies and artificial intelligence are developed and used responsibly and consistently with international law, including the well-established principles of international humanitarian Their development and use must contribute to international peace and security while advancing humanity's collective interests."},{"t":1121,"topic":"UN multilateralism","text":"The interest of humanity must always guide the development and use of these Mr. President, for Sri Lanka, the United Nations is an indispensable partner. The UN has stood with us in challenging times and supported our development. For many of us in the developing world, the United Nation is also an expression of a fundamental that every nation, la- large or small has a voice that every people has a right to dignity and development. And that in an interdependent world, no country should be left to confront global challenges For more than eight decades amidst its flaws and with much room for improvement the United Nations has given practical meaning to that promise. genuine faith in multilateralism requires the courage to acknowledge where the system has fallen short the humility to listen to those who feel and the determination to make our institutions more effective, more representative, and more responsive."},{"t":1204,"topic":"UN reform","text":"In this regard Sri Lanka supports the UN 80 initiative as an opportunity to renew and strengthen the United Nations and advance advance meaningful reform. Mr. President managing transformation cannot mean managing change for some while asking others merely to adapt to its The transformation taking place in our world must be inclusive. It must narrow rather than deepen the divides between north and south between those who say new technologies and those who merely receive them and between those who possesses resilience and those who are most exposed to global shocks. My country comes to this assembly not with the expectation that the United Nations can solve every problem but with the conviction that there are problems which no country can solve alone."},{"t":1267,"topic":"UN reform","text":"Our answer must therefore be a renewed faith in multilateralism and a United Nations that listens more closely, represents more fairly, and delivers for all. I thank you, Mr. &gt;&gt; I thank the Minister for Foreign Affairs of Sri Lanka."}],"compare":[{"topic":"UN & its reform","share":0.2349,"mean":0.2046,"rank":75,"others":170},{"topic":"Israel–Palestine","share":0.1053,"mean":0.0521,"rank":33,"others":76},{"topic":"Climate Change","share":0.0567,"mean":0.0427,"rank":58,"others":77},{"topic":"Middle East","share":0.0551,"mean":0.0071,"rank":12,"others":19},{"topic":"Nuclear Weapons","share":0.0534,"mean":0.0022,"rank":6,"others":6},{"topic":"Sri Lanka","share":0.0499,"mean":0.0,"rank":1,"others":0},{"topic":"Ocean Governance","share":0.0492,"mean":0.0065,"rank":13,"others":16}]};
